#!/usr/bin/env python3
"""Real local-HTTP acceptance for the maintained travel portal; no mock responses."""
import argparse,asyncio,json,time,uuid,traceback
from pathlib import Path
from datetime import date,timedelta
from playwright.async_api import async_playwright
HOST='localhost'
async def main(a):
 out=Path(a.output)/time.strftime('%Y%m%dT%H%M%S');out.mkdir(parents=True);origin='http://'+HOST+':8501';base=origin+'/travel/'+a.run
 report={'run':a.run,'started':time.time(),'scope':'Chromium on Fury through local HTTP; no external-device claim','checks':[],'console_errors':[]}
 def passed(name):report['checks'].append(name);print('PASS '+name,flush=True)
 async with async_playwright() as p:
  browser=await p.chromium.launch(args=['--no-sandbox']);ctx=await browser.new_context(viewport={'width':1440,'height':1000});page=await ctx.new_page();page.on('pageerror',lambda e:report['console_errors'].append(str(e)));page.on('dialog',lambda d:d.accept())
  async def api(method,path,body=None,target=page):
   return await target.evaluate('''async a=>{const token=sessionStorage.getItem('travel-token-'+a.rid);const r=await fetch('/api/travel/'+a.rid+'/backend',{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({method:a.method,path:a.path,body:a.body||{}})});if(!r.ok)throw Error('Transport HTTP '+r.status);return r.json()}''',{'rid':a.run,'method':method,'path':path,'body':body or {}})
  async def response(method,path,action,target=page):
   async with target.expect_response(lambda r:r.url.endswith('/backend') and r.request.method=='POST' and (r.request.post_data_json or {}).get('method')==method and (r.request.post_data_json or {}).get('path')==path) as pending:await action()
   return await (await pending.value).json()
  async def register(target):
   await target.goto(base);f=target.frame_locator('#app');await f.locator('#listing-list [data-detail]').first.wait_for();await f.locator('#auth-nav').click();await f.locator('[data-target=register-form]').click();email='portal'+uuid.uuid4().hex[:10]+'@example.test';password='PortalCheck2028!';await f.locator('#register-form [name=email]').fill(email);await f.locator('#register-form [name=password]').fill(password);r=await response('POST','/register',lambda:f.locator('#register-form button[type=submit]').click(),target);assert r['status']==201;await f.locator('#listing-list [data-detail]').first.wait_for();return f,email,password
  async def login(f,email,password):
   await f.locator('#auth-nav').click();await f.locator('[data-target=login-form]').click();await f.locator('#login-form [name=email]').fill(email);await f.locator('#login-form [name=password]').fill(password);r=await response('POST','/login',lambda:f.locator('#login-form button[type=submit]').click());assert r['status']==200
  try:
   await page.goto(base);f=page.frame_locator('#app');await f.locator('#listing-list .listing-card').first.wait_for();assert await f.locator('.hero-photo').evaluate('i=>i.complete&&i.naturalWidth>0');assert await f.locator('.destination-card').count()==6;assert await f.locator('#listing-list .listing-card img').first.evaluate('i=>i.complete&&i.naturalWidth>0');await page.screenshot(path=str(out/'desktop.png'));passed('Editorial discovery page, six destination scenes and loaded local imagery')
   await response('GET','/listings',lambda:f.locator('[data-destination=Kyoto]').click());await f.locator('#collection-title').filter(has_text='Kyoto').wait_for();assert 'Kyoto' in await f.locator('#listing-list').inner_text();await f.locator('#clear-filters').click();await f.locator('#collection-title').filter(has_text='Some places').wait_for()
   await f.locator('#max-price').fill('200');await f.locator('#search-party').select_option('2');await f.locator('#sort').select_option('price_asc');await response('GET','/listings',lambda:f.locator('#search-button').click());rows=(await api('GET','/listings',{'max_price':200,'party':2,'sort':'price_asc'}))['body']['listings'];assert rows and all(x['price']<=200 and x['capacity']>=2 for x in rows);assert [x['price'] for x in rows]==sorted(x['price'] for x in rows);passed('Destination selection, budget, party-size filter and server price sorting')
   await f.locator('#clear-filters').click();await f.locator('#next-page').wait_for(state='visible');await response('GET','/listings',lambda:f.locator('#next-page').click());await f.locator('#page-label').filter(has_text='Page 2').wait_for();await response('GET','/listings',lambda:f.locator('#prev-page').click());await f.locator('#page-label').filter(has_text='Page 1').wait_for();passed('Forward and backward server-backed pagination')
   f,email,password=await register(page);r=await response('POST','/favorites',lambda:f.locator('#listing-list [data-favorite]').first.click());assert r['status'] in (200,201);await f.locator('.nav-link[data-view=favorites]').click();await f.locator('#favorites [data-unfavorite]').first.wait_for();await page.reload();f=page.frame_locator('#app');await f.locator('#user-display').filter(has_text=email).wait_for();await f.locator('.nav-link[data-view=favorites]').click();await f.locator('#favorites [data-detail]').first.wait_for();passed('Registration and saved stays survive refresh and fresh backend processes')
   await f.locator('#favorites [data-detail]').first.click();await f.locator('#quote-form').wait_for();start=date.today()+timedelta(days=140)
   for name,value in {'check_in':str(start),'check_out':str(start+timedelta(days=2)),'party':'1'}.items():await f.locator('#quote-form [name='+name+']').fill(value)
   q=await response('POST','/quote',lambda:f.locator('#quote-button').click());assert q['status']==200;await f.locator('#quote-result').wait_for(state='visible');await f.locator('#check_out').fill(str(start+timedelta(days=3)));assert not await f.locator('#quote-result').is_visible();q=await response('POST','/quote',lambda:f.locator('#quote-button').click());reservation=await response('POST','/reservations',lambda:f.locator('#reserve-button').click());assert reservation['status']==201 and reservation['body']['reservation']['total']==q['body']['quote']['total'];saved=reservation['body']['reservation'];await f.locator('#reservation-confirmation').filter(has_text='confirmed').wait_for();await f.locator('#reservations-list .trip-card').first.wait_for();await page.screenshot(path=str(out/'confirmation.png'));passed('Detail, quote invalidation, server-calculated total and meaningful reservation confirmation')
   await f.locator('.nav-link[data-view=itineraries]').click();await f.locator('#itinerary-title').fill('A little time in Kyoto');await f.locator('#itinerary-notes').fill('Day 1 · Gardens and tea\nDay 2 · A slow morning');r=await response('POST','/itineraries',lambda:f.locator('#itinerary-form button[type=submit]').click());assert r['status']==201;plan=r['body']['itinerary'];await f.locator('[data-edit-itinerary]').first.click();await f.locator('#itinerary-title').fill('Three memorable days');await response('PUT','/itineraries/'+str(plan['id']),lambda:f.locator('#itinerary-form button[type=submit]').click());await f.locator('#itineraries-list').filter(has_text='Three memorable days').wait_for();passed('Private itinerary creation and real editing')
   second=await browser.new_context();p2=await second.new_page();_,email2,password2=await register(p2)
   for path,key in [('/favorites','favorites'),('/itineraries','itineraries'),('/reservations','reservations')]:assert (await api('GET',path,target=p2))['body'][key]==[]
   assert (await api('GET','/reservations/'+str(saved['id']),target=p2))['status']==404;assert (await api('PUT','/itineraries/'+str(plan['id']),{'title':'Not mine','notes':''},target=p2))['status']==404;assert (await api('GET','/admin/reservations',target=p2))['status']==403;await second.close();passed('Independent browser user cannot access saved stays, itineraries, reservations or admin records')
   await response('DELETE','/itineraries/'+str(plan['id']),lambda:f.locator('[data-delete-itinerary]').first.click());await f.locator('#itineraries-list .empty-state').wait_for();await f.locator('.nav-link[data-view=favorites]').click();await f.locator('[data-unfavorite]').first.wait_for();await response('DELETE','/favorites/'+str(saved['listing_id']),lambda:f.locator('[data-unfavorite]').first.click());await f.locator('#favorites-list .empty-state').wait_for();passed('Real itinerary deletion, wishlist removal and useful empty states')
   details={k:q['body']['quote'][k] for k in ('listing_id','check_in','check_out','party')};assert (await api('POST','/quote',{**details,'party':99}))['status']==400;assert (await api('POST','/quote',{**details,'check_out':details['check_in']}))['status']==400;key=uuid.uuid4().hex;tampered=await api('POST','/reservations',{**details,'request_key':key,'total':1});assert tampered['status']==201 and tampered['body']['reservation']['total']==q['body']['quote']['total'];assert (await api('POST','/reservations',{**details,'request_key':key}))['status']==409;passed('Backend rejects invalid dates/party, ignores client totals and prevents duplicate submissions')
   await f.locator('#logout').click();await f.locator('#auth-nav').wait_for();await login(f,email,password);await f.locator('.nav-link[data-view=reservations]').click();await f.locator('#reservations-list .trip-card').first.wait_for();assert (await api('GET','/reservations/'+str(saved['id'])))['status']==200;passed('Logout/login retrieves the existing reservation from persistent storage')
   await f.locator('#logout').click();await f.locator('#auth-nav').wait_for();await login(f,'admin@example.test','DemoAdmin2028!');await f.locator('.nav-link[data-view=admin]').click();await f.locator('#admin-reservations tbody tr').first.wait_for();inventory=(await api('GET','/admin/listings'))['body']['listings'];item=inventory[-1]
   await f.locator('[data-target=inventory-form]').click();await f.locator('#admin-listing-id option').first.wait_for(state='attached');await f.locator('#admin-listing-id').select_option(str(item['id']));await f.locator('#admin-price').fill(str(item['price']+1));await f.locator('#admin-active').select_option(str(item['active']))
   try:
    result=await response('PUT','/admin/listings/'+str(item['id']),lambda:f.locator('#inventory-form button[type=submit]').click());assert result['status']==200 and result['body']['listing']['price']==item['price']+1
   finally:assert (await api('PUT','/admin/listings/'+str(item['id']),{'price':item['price'],'active':item['active']}))['status']==200
   records=(await api('GET','/admin/reservations'))['body']['reservations'];assert records and all(not {'password','salt','token'}&set(row) for row in records);passed('Administrator reads sanitized records and edits actual inventory; original values restored')
   await page.set_viewport_size({'width':375,'height':812});assert await f.locator('body').evaluate('b=>b.scrollWidth<=innerWidth+1');assert not await f.locator('.main-nav').evaluate('n=>Array.from(n.querySelectorAll("button")).filter(b=>!b.hidden).some(b=>b.getBoundingClientRect().right>innerWidth+1)');await page.screenshot(path=str(out/'mobile-admin.png'));await f.locator('.nav-link[data-view=listings]').click();await f.locator('#listing-list .listing-card').first.wait_for();assert await f.locator('body').evaluate('b=>b.scrollWidth<=innerWidth+1');await page.screenshot(path=str(out/'mobile-discover.png'));passed('Mobile discovery, forms and administrator navigation fit375px')
   await page.set_viewport_size({'width':1440,'height':1000});await page.goto(origin+'/devteam?watch='+a.run);await page.wait_for_function("()=>document.getElementById('run-state').textContent==='finished'");await page.locator('[data-tab=build]').click();await page.frame_locator('#preview').frame_locator('#app').locator('.hero-photo').wait_for();docs=await page.evaluate('async u=>(await fetch(u)).json()','/api/travel/'+a.run+'/docs');assert docs['health']=='verified';await page.locator('details.backend summary').click();await page.locator('#hotels').click();await page.wait_for_function("()=>document.getElementById('api-output').textContent.includes('listings')");passed('Factory application preview, backend explorer and completed development state')
   assert not report['console_errors'],report['console_errors'];report['passed']=True
  except Exception as e:
   report.update(passed=False,error=str(e),traceback=traceback.format_exc());await page.screenshot(path=str(out/'failure.png'))
  finally:
   report['ended']=time.time();(out/'report.json').write_text(json.dumps(report,indent=2));await browser.close();print(json.dumps({'passed':report.get('passed'),'error':report.get('error'),'checks':len(report['checks']),'evidence':str(out)},indent=2))
 return report.get('passed',False)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--run',required=True);p.add_argument('--output',default='reports/travel-portal');raise SystemExit(0 if asyncio.run(main(p.parse_args())) else 1)
